#include <vector>
#include <algorithm>

class Solution {
public:
    bool canSortArray(std::vector<int>& nums) {
        int prev_max = -1;
        int i = 0, n = nums.size();
        while (i < n) {
            int cnt = __builtin_popcount(nums[i]);
            int cur_min = nums[i];
            int cur_max = nums[i];
            int j = i + 1;
            while (j < n && __builtin_popcount(nums[j]) == cnt) {
                cur_min = std::min(cur_min, nums[j]);
                cur_max = std::max(cur_max, nums[j]);
                j++;
            }
            if (prev_max > cur_min) return false;
            prev_max = cur_max;
            i = j;
        }
        return true;
    }
};

class Solution {
    public boolean canSortArray(int[] nums) {
        int prevMax = -1;
        int i = 0, n = nums.length;
        while (i < n) {
            int cnt = Integer.bitCount(nums[i]);
            int curMin = nums[i];
            int curMax = nums[i];
            int j = i + 1;
            while (j < n && Integer.bitCount(nums[j]) == cnt) {
                curMin = Math.min(curMin, nums[j]);
                curMax = Math.max(curMax, nums[j]);
                j++;
            }
            if (prevMax > curMin) return false;
            prevMax = curMax;
            i = j;
        }
        return true;
    }
}

